        countAvail -= n;
        bitsAvail <<= n;
      }
      assert(count == rectInfo.bitsPerSample);
      return value;
    };

    if (rectInfo.bitsPerSample == bitsPerSrcPixel) {
      // Fast path: bits per sample matches source pixel size
      loop(process_word);
    } else {
      // Slow path: bits per sample does not match source pixel size
      loop(process_bits);
    }
